alter policy myway_documents_upload_own on storage.objects with check (bucket_id = 'myway-documents' and name ~ '^[0-9a-f-]{36}/[a-zA-Z0-9_-]{1,128}$' and (storage.foldername(name))[1] = (select auth.uid())::text and not exists (select 1 from public.user_documents d where d.user_id = (select auth.uid()) and d.id = storage.filename(storage.objects.name) and d.deleted_at is not null));
